methods.generateQRCode:
async function() {
  try {
    const token = localStorage.getItem('token')
    const res = await fetch('/api/auth/qrcode/generate', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      }
    })
    const data = await res.json()
    if (data.uuid) {
      this.uuid = data.uuid
      this.qrImage = data.qr_image_base64
      this.status = 'pending'
      this.startCountdown()
      this.startPolling()
    }
  } catch (error) {
    console.error('生成二维码失败:', error)
  }
}

methods.startCountdown:
function() {
  this.countdown = 60
  this.countdownTimer = setInterval(() => {
    this.countdown--
    if (this.countdown <= 0) {
      clearInterval(this.countdownTimer)
      this.status = 'expired'
    }
  }, 1000)
}

methods.startPolling:
async function() {
  const poll = async () => {
    try {
      const res = await fetch(`/api/auth/qrcode/${this.uuid}/status`)
      const data = await res.json()

      if (data.status === 'confirmed') {
        localStorage.setItem('token', data.token)
        this.status = 'confirmed'
        window.location.href = '/'
      } else if (data.status === 'expired') {
        this.status = 'expired'
      } else {
        setTimeout(poll, 1500)
      }
    } catch (error) {
      console.error('轮询状态失败:', error)
    }
  }
  poll()
}
